"CP-2(1)": {"statement":[{"prose":"Coordinate contingency plan development with organizational elements responsible for related plans."}],"discussion":["Plans that are related to contingency plans include Business Continuity Plans, Disaster Recovery Plans, Critical Infrastructure Plans, Continuity of Operations Plans, Crisis Communications Plans, Insider Threat Implementation Plans, Data Breach Response Plans, Cyber Incident Response Plans, Breach Response Plans, and Occupant Emergency Plans."],"params":[],"related":[],"objectives":[{"id":"cp-2.1_obj","label":"CP-02(01)","prose":"contingency plan development is coordinated with organizational elements responsible for related plans."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business contingency plans","disaster recovery plans","continuity of operations plans","crisis communications plans","critical infrastructure plans","cyber incident response plan","insider threat implementation plans","occupant emergency plans","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with information security responsibilities","personnel with responsibility for related plans"]}],"references":[]},
"CP-2(2)": {"statement":[{"prose":"Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations."}],"discussion":["Capacity planning is needed because different threats can result in a reduction of the available processing, telecommunications, and support services intended to support essential mission and business functions. Organizations anticipate degraded operations during contingency operations and factor the degradation into capacity planning. For capacity planning, environmental support refers to any environmental factor for which the organization determines that it needs to provide support in a contingency situation, even if in a degraded state. Such determinations are based on an organizational assessment of risk, system categorization (impact level), and organizational risk tolerance."],"params":[],"related":["PE-11","PE-12","PE-13","PE-14","PE-18","SC-5"],"objectives":[{"id":"cp-2.2_obj-1","label":"CP-02(02)[01]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for information processing;"},{"id":"cp-2.2_obj-2","label":"CP-02(02)[02]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for telecommunications;"},{"id":"cp-2.2_obj-3","label":"CP-02(02)[03]","prose":"capacity planning is conducted so that the necessary capacity exists during contingency operations for environmental support."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","capacity planning documents","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel responsible for capacity planning","organizational personnel with information security responsibilities"]}],"references":[]},
"CP-2(3)": {"statement":[{"prose":"Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation."}],"discussion":["Organizations may choose to conduct contingency planning activities to resume mission and business functions as part of business continuity planning or as part of business impact analyses. Organizations prioritize the resumption of mission and business functions. The time period for resuming mission and business functions may be dependent on the severity and extent of the disruptions to the system and its supporting infrastructure."],"params":[{"id":"CP-02(03)_ODP[01]","kind":"Selection","value":"[Selection: all; essential]"},{"id":"CP-02(03)_ODP[02]","kind":"Assignment","value":"[Assignment: organization-defined time period]","guideline":"the contingency plan activation time period within which to resume mission and business functions is defined"}],"related":[],"objectives":[{"id":"cp-2.3_obj","label":"CP-02(03)","prose":"the resumption of [Selection: all; essential] mission and business functions are planned for within [Assignment: organization-defined time period] of contingency plan activation."}],"methods":[{"method":"Examine","objects":["Contingency planning policy","procedures addressing contingency operations for the system","contingency plan","business impact assessment","system security plan","privacy plan","other related plans","system security plan","other relevant documents or records"]},{"method":"Interview","objects":["Organizational personnel with contingency planning and plan implementation responsibilities","organizational personnel with information security and privacy responsibilities","organizational personnel with knowledge of requirements for mission and business functions"]},{"method":"Test","objects":["Organizational processes for resumption of missions and business functions"]}],"references":[]},
